Function info: FunctionInfo(name='BSP_PB_Init', file_path='/Users/jie/Documents/workspace/lcmhalgen/posixGen_Demos/UART_Hyperterminal_IT/Drivers/BSP/STM324xG_EVAL/stm324xg_eval.c', location_line=281, function_content='/**
* @brief  Configures button GPIO and EXTI Line.
* @param  Button: Button to be configured
*          This parameter can be one of the following values:
*            @arg  BUTTON_WAKEUP: Wakeup Push Button
*            @arg  BUTTON_TAMPER: Tamper Push Button
*            @arg  BUTTON_KEY: Key Push Button
*            @arg  BUTTON_RIGHT: Joystick Right Push Button
*            @arg  BUTTON_LEFT: Joystick Left Push Button
*            @arg  BUTTON_UP: Joystick Up Push Button
*            @arg  BUTTON_DOWN: Joystick Down Push Button
*            @arg  BUTTON_SEL: Joystick Sel Push Button
* @param  Button_Mode: Button mode
*          This parameter can be one of the following values:
*            @arg  BUTTON_MODE_GPIO: Button will be used as simple IO
*            @arg  BUTTON_MODE_EXTI: Button will be connected to EXTI line
*                                    with interrupt generation capability
*/
void BSP_PB_Init(Button_TypeDef Button, ButtonMode_TypeDef Button_Mode)
{
  GPIO_InitTypeDef GPIO_InitStruct;

  /* Enable the BUTTON clock */
  BUTTONx_GPIO_CLK_ENABLE(Button);

  if(Button_Mode == BUTTON_MODE_GPIO)
  {
    /* Configure Button pin as input */
    GPIO_InitStruct.Pin = BUTTON_PIN[Button];
    GPIO_InitStruct.Mode = GPIO_MODE_INPUT;
    GPIO_InitStruct.Pull = GPIO_NOPULL;
    GPIO_InitStruct.Speed = GPIO_SPEED_FAST;

    HAL_GPIO_Init(BUTTON_PORT[Button], &GPIO_InitStruct);
  }

  if(Button_Mode == BUTTON_MODE_EXTI)
  {
    /* Configure Button pin as input with External interrupt */
    GPIO_InitStruct.Pin = BUTTON_PIN[Button];
    GPIO_InitStruct.Pull = GPIO_NOPULL;
    GPIO_InitStruct.Speed = GPIO_SPEED_FAST;

    if(Button != BUTTON_WAKEUP)
    {
      GPIO_InitStruct.Mode = GPIO_MODE_IT_FALLING; 
    }
    else
    {
      GPIO_InitStruct.Mode = GPIO_MODE_IT_RISING;
    }

    HAL_GPIO_Init(BUTTON_PORT[Button], &GPIO_InitStruct);

    /* Enable and set Button EXTI Interrupt to the lowest priority */
    HAL_NVIC_SetPriority((IRQn_Type)(BUTTON_IRQn[Button]), 0x0F, 0x0);
    HAL_NVIC_EnableIRQ((IRQn_Type)(BUTTON_IRQn[Button]));
  }
}
