void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Minimal interrupt handler for emulation - avoid all hardware dependencies */

  /* In emulation, we need to avoid any operations that might cause loops or recursion */
  /* The simplest approach is to just update the state and call appropriate callbacks */

  /* Check for receive completion */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate that data has been received */
    if (huart->pRxBuffPtr != NULL && huart->RxXferSize > 0 && huart->RxXferCount > 0)
    {
      /* Read data if available, but don't block */
      int bytes_read = 0;
      if (huart->RxXferCount > 0)
      {
        /* Try to read one byte at a time for interrupt mode */
        bytes_read = HAL_BE_In(huart->pRxBuffPtr, 1);
        if (bytes_read > 0)
        {
          huart->pRxBuffPtr += bytes_read;
          huart->RxXferCount -= bytes_read;
        }
      }

      /* If all data received or we got some data, update state */
      if (huart->RxXferCount == 0 || bytes_read > 0)
      {
        /* Update state */
        huart->RxState = HAL_UART_STATE_READY;

        /* Call appropriate callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->RxCpltCallback != NULL)
        {
          huart->RxCpltCallback(huart);
        }
#else
        HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
      }
    }
    return;
  }

  /* Check for transmit completion */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Simulate transmission complete */
    huart->gState = HAL_UART_STATE_READY;

    /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->TxCpltCallback != NULL)
    {
      huart->TxCpltCallback(huart);
    }
#else
    HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    return;
  }

  /* Handle error cases - just clear error code */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    /* Clear error code */
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }

  /* For any other case, do nothing to avoid issues */
  /* The original function would check various hardware flags */
  /* In emulation, we skip all hardware checks to avoid loops */
}

